import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-0-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  const imageUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  if (imageUrl && ctx.textureLoader) {
    map = ctx.textureLoader.load(imageUrl);
    map.colorSpace = THREE.SRGBColorSpace;

    // atlas region mapping
    const atlasW = 512, atlasH = 320;
    const rectX = 0, rectY = 0, rectW = 512, rectH = 320;
    const uOffset = rectX / atlasW;
    const vOffset = 1 - (rectY + rectH) / atlasH;
    const uScale = rectW / atlasW;
    const vScale = rectH / atlasH;

    const uvNode = uv().mul([uScale, vScale]).add([uOffset, vOffset]);
    material.colorNode = texture(map, uvNode);
  } else {
    material.colorNode = vec4(
      float(0x16 / 255), float(0x16 / 255), float(0x1d / 255), 1
    );
  }

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-card-3-label-plane';
  group.add(plane);

  // headline text: "Pricing 3"
  let textMesh = null;
  if (ctx.fontAtlas) {
    textMesh = createTextMesh({
      text: 'Pricing 3',
      font: 'Lora',
      weight: 400,
      sizeEm: 0.34,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      align: 'center',
      anchor: 'center',
    });
    textMesh.position.set(0, 0, 0.001);
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose();
      textMesh.material?.dispose();
    }
  };

  return group;
}
